module traffic_light (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] x0,\n    input [7:0] r0,\n    input [7:0] g0,\n    input [7:0] x1,\n    input [7:0] r1,\n    input [7:0] g1,\n    input [7:0] x2,\n    input [7:0] r2,\n    input [7:0] g2,\n    input [7:0] x3,\n    input [7:0] r3,\n    input [7:0] g3,\n    output reg [31:0] prob0,\n    output reg [31:0] prob1,\n    output reg [31:0] prob2,\n    output reg [31:0] prob3,\n    output reg [31:0] prob_all,\n    output reg done\n);\n\n// State definitions\nlocalparam [2:0] IDLE            = 3'd0;\nlocalparam [2:0] COMPUTE_LCM     = 3'd1;\nlocalparam [2:0] PREPARE_LOOP    = 3'd2;\nlocalparam [2:0] LOOP_CHECK      = 3'd3;\nlocalparam [2:0] CALCULATE_PROB  = 3'd4;\nlocalparam [2:0] FINISHED        = 3'd5;\n\nreg [2:0] state;\nreg [15:0] current_lcm;\nreg [7:0] lcm_index;\nreg [15:0] t_counter;\nreg [15:0] cnt_0, cnt_1, cnt_2, cnt_3, cnt_all;\n\n// Light registers\nreg [7:0] x [0:3];\nreg [7:0] r [0:3];\nreg [7:0] g [0:3];\nreg [7:0] T [0:3];\n\n// Computation variables\nreg [15:0] mod_result;\nreg found_red;\nreg [1:0] light_index;\n\n// Division variables\nreg [31:0] numerator;\nreg [15:0] denominator;\nreg [31:0] quotient;\nreg [4:0] div_counter;\nreg [2:0] prob_index;\n\n// GCD function\nfunction automatic [15:0] gcd(input [15:0] a, input [15:0] b);\n    reg [15:0] temp;\n    begin\n        while (b != 0) begin\n            temp = b;\n            b = a % b;\n            a = temp;\n        end\n        gcd = a;\n    end\nendfunction\n\n// LCM function\nfunction automatic [15:0] lcm(input [15:0] a, input [15:0] b);\n    begin\n        if (a == 0 || b == 0)\n            lcm = 0;\n        else\n            lcm = (a / gcd(a, b)) * b;\n    end\nendfunction\n\ninteger i;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        prob0 <= 32'd0;\n        prob1 <= 32'd0;\n        prob2 <= 32'd0;\n        prob3 <= 32'd0;\n        prob_all <= 32'd0;\n        current_lcm <= 16'd1;\n        cnt_0 <= 16'd0;\n        cnt_1 <= 16'd0;\n        cnt_2 <= 16'd0;\n        cnt_3 <= 16'd0;\n        cnt_all <= 16'd0;\n        div_counter <= 5'd0;\n        for (i = 0; i < 4; i = i + 1) begin\n            x[i] <= 8'd0;\n            r[i] <= 8'd0;\n            g[i] <= 8'd0;\n            T[i] <= 8'd0;\n        end\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                cnt_0 <= 16'd0;\n                cnt_1 <= 16'd0;\n                cnt_2 <= 16'd0;\n                cnt_3 <= 16'd0;\n                cnt_all <= 16'd0;\n                t_counter <= 16'd0;\n                if (start) begin\n                    x[0] <= x0; r[0] <= r0; g[0] <= g0;\n                    x[1] <= x1; r[1] <= r1; g[1] <= g1;\n                    x[2] <= x2; r[2] <= r2; g[2] <= g2;\n                    x[3] <= x3; r[3] <= r3; g[3] <= g3;\n                    T[0] <= r0 + g0;\n                    T[1] <= r1 + g1;\n                    T[2] <= r2 + g2;\n                    T[3] <= r3 + g3;\n                    state <= COMPUTE_LCM;\n                    lcm_index <= 4'd0;\n                end\n            end\n\n            COMPUTE_LCM: begin\n                if (lcm_index < 4) begin\n                    current_lcm <= lcm(current_lcm, T[lcm_index]);\n                    lcm_index <= lcm_index + 1;\n                end else begin\n                    state <= PREPARE_LOOP;\n                end\n            end\n\n            PREPARE_LOOP: begin\n                if (current_lcm == 0) begin\n                    state <= FINISHED;\n                end else if (t_counter < current_lcm) begin\n                    light_index <= 2'd0;\n                    found_red <= 1'b0;\n                    state <= LOOP_CHECK;\n                end else begin\n                    state <= CALCULATE_PROB;\n                    prob_index <= 3'd0;\n                    div_counter <= 5'd0;\n                end\n            end\n\n            LOOP_CHECK: begin\n                if (light_index < 4) begin\n                    mod_result = (t_counter + x[light_index]) % T[light_index];\n\n                    if (mod_result < r[light_index]) begin\n                        // Red light\n                        case (light_index)\n                            2'd0: cnt_0 <= cnt_0 + 1;\n                            2'd1: cnt_1 <= cnt_1 + 1;\n                            2'd2: cnt_2 <= cnt_2 + 1;\n                            2'd3: cnt_3 <= cnt_3 + 1;\n                        endcase\n                        found_red <= 1'b1;\n                    end\n\n                    light_index <= light_index + 1;\n                end else begin\n                    if (!found_red) cnt_all <= cnt_all + 1;\n                    t_counter <= t_counter + 1;\n                    state <= PREPARE_LOOP;\n                end\n            end\n\n            CALCULATE_PROB: begin\n                if (prob_index == 0) begin\n                    numerator <= {cnt_0, 16'd0};  // Shift left 16\n                    denominator <= current_lcm;\n                    quotient <= 32'd0;\n                    div_counter <= 5'd0;\n                    prob_index <= prob_index + 1;\n                end\n                else if (prob_index < 5) begin\n                    if (div_counter < 5'd31) begin\n                        if (numerator >= denominator) begin\n                            numerator <= numerator - denominator;\n                            quotient <= {quotient[30:0], 1'b1};\n                        end else begin\n                            quotient <= {quotient[30:0], 1'b0};\n                        end\n                        numerator <= numerator << 1;\n                        div_counter <= div_counter + 1;\n                    end\n                    else begin\n                        case (prob_index)\n                            3'd1: prob0 <= quotient;\n                            3'd2: begin\n                                prob1 <= quotient;\n                                numerator <= {cnt_1, 16'd0};\n                                denominator <= current_lcm;\n                            end\n                            3'd3: begin\n                                prob2 <= quotient;\n                                numerator <= {cnt_2, 16'd0};\n                                denominator <= current_lcm;\n                            end\n                            3'd4: begin\n                                prob3 <= quotient;\n                                numerator <= {cnt_3, 16'd0};\n                                denominator <= current_lcm;\n                            end\n                        endcase\n\n                        if (prob_index == 4'd4) begin\n                            numerator <= {cnt_all, 16'd0};\n                            denominator <= current_lcm;\n                        end\n\n                        div_counter <= 5'd0;\n                        quotient <= 32'd0;\n                        prob_index <= prob_index + 1;\n                    end\n                end\n                else if (prob_index == 5) begin\n                    if (div_counter < 5'd31) begin\n                        if (numerator >= denominator) begin\n                            numerator <= numerator - denominator;\n                            quotient <= {quotient[30:0], 1'b1};\n                        end else begin\n                            quotient <= {quotient[30:0], 1'b0};\n                        end\n                        numerator <= numerator << 1;\n                        div_counter <= div_counter + 1;\n                    end\n                    else begin\n                        prob_all <= quotient;\n                        state <= FINISHED;\n                    end\n                end\n            end\n\n            FINISHED: begin\n                done <= 1'b1;\n                if (!start) begin\n                    state <= IDLE;\n                end\n            end\n\n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule